  __ovr_X_H__initial = pop!(__overrides, "X_H__initial", nothing); isnothing(__ovr_X_H__initial) || (__initial_conditions[X_H] = __ovr_X_H__initial)
  __ovr_X_H__guess = pop!(__overrides, "X_H__guess", nothing)
  __ovr_Y_H = pop!(__overrides, "Y_H", nothing); isnothing(__ovr_Y_H) || push!(__eqs, Y_H ~ __ovr_Y_H)
  __ovr_Y_H__initial = pop!(__overrides, "Y_H__initial", nothing); isnothing(__ovr_Y_H__initial) || (__initial_conditions[Y_H] = __ovr_Y_H__initial)
  __ovr_Y_H__guess = pop!(__overrides, "Y_H__guess", nothing)
  __ovr_N_H = pop!(__overrides, "N_H", nothing); isnothing(__ovr_N_H) || push!(__eqs, N_H ~ __ovr_N_H)
  __ovr_N_H__initial = pop!(__overrides, "N_H__initial", nothing); isnothing(__ovr_N_H__initial) || (__initial_conditions[N_H] = __ovr_N_H__initial)
  __ovr_N_H__guess = pop!(__overrides, "N_H__guess", nothing)
  __ovr_X_A = pop!(__overrides, "X_A", nothing); isnothing(__ovr_X_A) || push!(__eqs, X_A ~ __ovr_X_A)
  __ovr_X_A__initial = pop!(__overrides, "X_A__initial", nothing); isnothing(__ovr_X_A__initial) || (__initial_conditions[X_A] = __ovr_X_A__initial)
  __ovr_X_A__guess = pop!(__overrides, "X_A__guess", nothing)
  __ovr_Y_A = pop!(__overrides, "Y_A", nothing); isnothing(__ovr_Y_A) || push!(__eqs, Y_A ~ __ovr_Y_A)
  __ovr_Y_A__initial = pop!(__overrides, "Y_A__initial", nothing); isnothing(__ovr_Y_A__initial) || (__initial_conditions[Y_A] = __ovr_Y_A__initial)
  __ovr_Y_A__guess = pop!(__overrides, "Y_A__guess", nothing)
  __ovr_N_A = pop!(__overrides, "N_A", nothing); isnothing(__ovr_N_A) || push!(__eqs, N_A ~ __ovr_N_A)
  __ovr_N_A__initial = pop!(__overrides, "N_A__initial", nothing); isnothing(__ovr_N_A__initial) || (__initial_conditions[N_A] = __ovr_N_A__initial)
  __ovr_N_A__guess = pop!(__overrides, "N_A__guess", nothing)
  __ovr_F_H = pop!(__overrides, "F_H", nothing); isnothing(__ovr_F_H) || push!(__eqs, F_H ~ __ovr_F_H)
  __ovr_F_H__initial = pop!(__overrides, "F_H__initial", nothing); isnothing(__ovr_F_H__initial) || (__initial_conditions[F_H] = __ovr_F_H__initial)
  __ovr_F_H__guess = pop!(__overrides, "F_H__guess", nothing)
  __ovr_F_A = pop!(__overrides, "F_A", nothing); isnothing(__ovr_F_A) || push!(__eqs, F_A ~ __ovr_F_A)
  __ovr_F_A__initial = pop!(__overrides, "F_A__initial", nothing); isnothing(__ovr_F_A__initial) || (__initial_conditions[F_A] = __ovr_F_A__initial)
  __ovr_F_A__guess = pop!(__overrides, "F_A__guess", nothing)
  __ovr_tau = pop!(__overrides, "tau", nothing); isnothing(__ovr_tau) || push!(__eqs, tau ~ __ovr_tau)
  __ovr_tau__initial = pop!(__overrides, "tau__initial", nothing); isnothing(__ovr_tau__initial) || (__initial_conditions[tau] = __ovr_tau__initial)
  __ovr_tau__guess = pop!(__overrides, "tau__guess", nothing)

  ### Constants
  __constants = Any[]

  ### Components
  push!(__systems, @named frame_a = __Dyad__Frame3D())
  # Subcomponent force of type MultibodyComponents.WorldForce
  force_overrides = __pop_subcomponent_overrides!(__overrides, "force")
  push!(__systems, @named force = MultibodyComponents.WorldForce(; resolve_in_frame=MultibodyComponents.ResolveInFrame.FrameB(), render=false, force_overrides...))
  # Subcomponent torque of type MultibodyComponents.WorldTorque
  torque_overrides = __pop_subcomponent_overrides!(__overrides, "torque")
  push!(__systems, @named torque = MultibodyComponents.WorldTorque(; resolve_in_frame=MultibodyComponents.ResolveInFrame.FrameB(), torque_overrides...))

  ### Check there are no unmatched overrides
  isempty(__overrides) || throw(ArgumentError("overrides: [$(join(keys(__overrides), ", "))] don't match names found in model. These names may exist in the model but could have been conditionally excluded."))

  ### Guesses
  isnothing(__ovr_r_cof__guess) || (__guesses[r_cof] = __ovr_r_cof__guess)
  isnothing(__ovr_r_am__guess) || (__guesses[r_am] = __ovr_r_am__guess)
  isnothing(__ovr_v_frame__guess) || (__guesses[v_frame] = __ovr_v_frame__guess)
  isnothing(__ovr_w__guess) || (__guesses[w] = __ovr_w__guess)
  isnothing(__ovr_v_cof__guess) || (__guesses[v_cof] = __ovr_v_cof__guess)
  isnothing(__ovr_u__guess) || (__guesses[u] = __ovr_u__guess)
  isnothing(__ovr_v__guess) || (__guesses[v] = __ovr_v__guess)
  isnothing(__ovr_r__guess) || (__guesses[r] = __ovr_r__guess)
  isnothing(__ovr_U__guess) || (__guesses[U] = __ovr_U__guess)
  isnothing(__ovr_v_nd__guess) || (__guesses[v_nd] = __ovr_v_nd__guess)
  isnothing(__ovr_r_nd__guess) || (__guesses[r_nd] = __ovr_r_nd__guess)
  isnothing(__ovr_NonDimXY__guess) || (__guesses[NonDimXY] = __ovr_NonDimXY__guess)
  isnothing(__ovr_NonDimN__guess) || (__guesses[NonDimN] = __ovr_NonDimN__guess)
  isnothing(__ovr_X_H__guess) || (__guesses[X_H] = __ovr_X_H__guess)
  isnothing(__ovr_Y_H__guess) || (__guesses[Y_H] = __ovr_Y_H__guess)
  isnothing(__ovr_N_H__guess) || (__guesses[N_H] = __ovr_N_H__guess)
  isnothing(__ovr_X_A__guess) || (__guesses[X_A] = __ovr_X_A__guess)
  isnothing(__ovr_Y_A__guess) || (__guesses[Y_A] = __ovr_Y_A__guess)
  isnothing(__ovr_N_A__guess) || (__guesses[N_A] = __ovr_N_A__guess)
  isnothing(__ovr_F_H__guess) || (__guesses[F_H] = __ovr_F_H__guess)
  isnothing(__ovr_F_A__guess) || (__guesses[F_A] = __ovr_F_A__guess)
  isnothing(__ovr_tau__guess) || (__guesses[tau] = __ovr_tau__guess)

  ### Initialization Equations

  ### Assertions
  __assertions = []

  ### Equations
  push!(__eqs, r_cof ~ [Lpp / 2, 0, MeanDraft / 2])
  push!(__eqs, r_am ~ [Lpp / 2 + Xg, 0, MeanDraft / 2])
  push!(__eqs, v_frame ~ MultibodyComponents.resolve2(frame_a.R, ModelingToolkit.D_nounits(frame_a.r_0) - [Current_x, Current_y, 0]))
  push!(__eqs, w ~ MultibodyComponents.angular_velocity2(frame_a.R))
  push!(__eqs, v_cof ~ v_frame + MultibodyComponents.cross(w, r_cof))
  push!(__eqs, u ~ v_cof[1])
  push!(__eqs, v ~ v_cof[2])
  push!(__eqs, r ~ w[3])
  push!(__eqs, U ~ sqrt(u ^ 2 + v ^ 2 + U_floor ^ 2))
  push!(__eqs, U_out ~ U)
  push!(__eqs, v_nd ~ v / U)
  push!(__eqs, r_nd ~ r * Lpp / U)
  push!(__eqs, NonDimXY ~ 0.5 * SeaDensity * U ^ 2 * Lpp * Draft)
  push!(__eqs, NonDimN ~ NonDimXY * Lpp)
  push!(__eqs, Resistance ~ -(R3 * u * u * abs(u) + R2 * u * abs(u) + R1 * u))
  push!(__eqs, ResistancePower ~ Resistance * u)
  push!(__eqs, X_H ~ Resistance + NonDimXY * (X_vv * v_nd ^ 2 + X_vvvv * v_nd ^ 4 + X_rr * r_nd ^ 2 + X_vr * v_nd * r_nd))
  push!(__eqs, Y_H ~ NonDimXY * (Y_v * v_nd + Y_vvv * v_nd ^ 3 + Y_r * r_nd + Y_rrr * r_nd ^ 3 + Y_vrr * v_nd * r_nd ^ 2 + Y_vvr * v_nd ^ 2 * r_nd))
  push!(__eqs, N_H ~ NonDimN * (N_v * v_nd + N_vvv * v_nd ^ 3 + N_r * r_nd + N_rrr * r_nd ^ 3 + N_vrr * v_nd * r_nd ^ 2 + N_vvr * v_nd ^ 2 * r_nd))
  push!(__eqs, X_A ~ -Displacement * (mx * ModelingToolkit.D_nounits(u) - my * v * r))
  push!(__eqs, Y_A ~ -Displacement * (my * ModelingToolkit.D_nounits(v) + mx * u * r))
  push!(__eqs, N_A ~ -Displacement * Jz * ModelingToolkit.D_nounits(r))
  push!(__eqs, F_H ~ [X_H, Y_H, 0])
  push!(__eqs, F_A ~ [X_A, Y_A, 0])
  push!(__eqs, tau ~ MultibodyComponents.cross(r_cof, F_H) + MultibodyComponents.cross(r_am, F_A) + [0, 0, N_H + N_A])
  push!(__eqs, force.force_x ~ F_H[1] + F_A[1])
  push!(__eqs, force.force_y ~ F_H[2] + F_A[2])
  push!(__eqs, force.force_z ~ 0)
  push!(__eqs, torque.torque_x ~ tau[1])
  push!(__eqs, torque.torque_y ~ tau[2])
  push!(__eqs, torque.torque_z ~ tau[3])
  push!(__eqs, connect(frame_a, force.frame_b, torque.frame_b))

  # Return completely constructed System
  return System(__eqs, t, __vars, __params; systems=__systems, initial_conditions=__initial_conditions, guesses=__guesses, name, initialization_eqs=__initialization_eqs, bindings=__bindings, assertions=__assertions)
end
export HydrodynamicXYY
